class MainActivity:ComponentActivity(){ override fun onCreate(b:Bundle?){super.onCreate(b);setContent { RaahatTheme { RaahatApp() } }} }

@Composable fun RaahatTheme(content: @Composable () -> Unit){ MaterialTheme(colorScheme=darkColorScheme(primary=Cyan,secondary=Emerald,background=Navy,surface=Panel,onBackground=Soft,onSurface=Soft,error=Red),content=content) }

@Composable fun RaahatApp(vm:RaahatViewModel= viewModel()){
    Surface(modifier=Modifier.fillMaxSize(),color=Navy,contentColor=Soft){ Box(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(Navy,Color(0xFF071B28),Navy)))){
        AnimatedContent(vm.screen,transitionSpec={fadeIn(tween(450))+slideInHorizontally{it/8} togetherWith fadeOut(tween(250))},label="screen") { s ->
            when(s){ Screen.SPLASH->Splash(); Screen.ROLE->Role(vm); Screen.CITIZEN->Citizen(vm); Screen.REPORT->Report(vm); Screen.VERIFY->Verify(vm); Screen.COMMAND->Command(vm); Screen.INCIDENT->Incident(vm); Screen.STRATEGY->Strategy(vm); Screen.EXECUTE->Execute(vm); Screen.IMPACT->Impact(vm); Screen.CITY->CityPulse(vm); Screen.COPILOT->Copilot(vm) }
        }
    } }
}

