@Composable fun Metric(value:String,label:String,mod:Modifier,color:Color=Soft){Column(mod.background(Soft.copy(.055f),RoundedCornerShape(16.dp)).padding(13.dp)){Text(value,fontSize=22.sp,fontWeight=FontWeight.Bold,color=color);Text(label,fontSize=10.sp,color=Soft.copy(.55f))}}
@Composable fun RiskRing(value:Int,label:String,color:Color,size:Dp){Box(Modifier.size(size),contentAlignment=Alignment.Center){Canvas(Modifier.fillMaxSize()){drawArc(Soft.copy(.08f),-90f,360f,false,style=Stroke(9f,cap=StrokeCap.Round));drawArc(color,-90f,value*3.6f,false,style=Stroke(9f,cap=StrokeCap.Round))};Column(horizontalAlignment=Alignment.CenterHorizontally){Text("$value",fontSize=(size.value*.2).sp,fontWeight=FontWeight.Black);Text(label,fontSize=8.sp,color=color,fontWeight=FontWeight.Bold)}}}
@Composable fun SectionTitle(t:String){Text(t,fontSize=11.sp,color=Soft.copy(.55f),letterSpacing=1.4.sp,fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=24.dp,bottom=10.dp))}
@Composable fun Label(t:String){Text(t,fontSize=10.sp,color=Cyan,letterSpacing=1.4.sp,fontWeight=FontWeight.Bold)}
@Composable fun Live(t:String){Row(verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(6.dp).background(Emerald,CircleShape));Spacer(Modifier.width(6.dp));Text(t,fontSize=9.sp,color=Emerald,letterSpacing=1.sp)}}
@Composable fun Pill(t:String,c:Color,mod:Modifier=Modifier){Text(t,fontSize=9.sp,color=c,fontWeight=FontWeight.Bold,letterSpacing=.7.sp,modifier=mod.background(c.copy(.12f),CircleShape).border(1.dp,c.copy(.35f),CircleShape).padding(horizontal=10.dp,vertical=6.dp))}
@Composable fun IncidentRow(name:String,status:String,sub:String,color:Color,onClick:()->Unit){Row(Modifier.fillMaxWidth().clickable(onClick=onClick).padding(vertical=11.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(12.dp).background(color,CircleShape));Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text(name,fontWeight=FontWeight.Bold);Text(sub,fontSize=11.sp,color=Soft.copy(.5f))};Text(status,fontSize=9.sp,color=color);Icon(Icons.Default.ChevronRight,null,tint=Soft.copy(.4f))}}
@Composable fun Forecast(p:PredictedZone){Row(Modifier.fillMaxWidth().padding(vertical=7.dp).background(Cyan.copy(.05f),RoundedCornerShape(15.dp)).padding(13.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.TrendingUp,null,tint=Cyan);Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text(p.name,fontWeight=FontWeight.Bold);Text("Expected ${p.eta}",fontSize=11.sp,color=Soft.copy(.55f))};Text("${p.probability}%",fontSize=20.sp,fontWeight=FontWeight.Bold,color=if(p.probability>60)Red else Amber)}}
@Composable fun Timeline(time:String,title:String,last:Boolean){Row(Modifier.height(46.dp)){Column(horizontalAlignment=Alignment.CenterHorizontally){Box(Modifier.size(9.dp).background(if(last)Red else Cyan,CircleShape));if(!last)Box(Modifier.width(1.dp).weight(1f).background(Cyan.copy(.25f)))};Text(time,Modifier.width(58.dp).padding(start=10.dp),fontSize=11.sp,color=Cyan);Text(title,fontSize=12.sp,color=if(last)Soft else Soft.copy(.7f))}}
@Composable fun SimStat(v:String,l:String,m:Modifier){Column(m){Text(v,fontSize=19.sp,fontWeight=FontWeight.Bold,color=Cyan);Text(l,fontSize=9.sp,color=Soft.copy(.5f))}}
@Composable fun BeforeAfter(label:String,before:String,after:String,beforeC:Color,afterC:Color){Row(Modifier.fillMaxWidth().padding(vertical=8.dp).background(Soft.copy(.04f),RoundedCornerShape(14.dp)).padding(13.dp),verticalAlignment=Alignment.CenterVertically){Text(label,Modifier.weight(1f),fontSize=12.sp);Text(before,color=beforeC,fontSize=12.sp);Icon(Icons.Default.ArrowForward,null,tint=Soft.copy(.35f),modifier=Modifier.padding(horizontal=9.dp).size(15.dp));Text(after,color=afterC,fontWeight=FontWeight.Bold,fontSize=12.sp)}}
@Composable fun ImpactRing(v:Int,l:String,m:Modifier){Column(m,horizontalAlignment=Alignment.CenterHorizontally){RiskRing(v,"%",Emerald,82.dp);Text(l,fontSize=11.sp,modifier=Modifier.padding(top=7.dp))}}
@Composable fun DemoStrip(){Row(Modifier.fillMaxWidth().padding(top=12.dp).background(Cyan.copy(.1f),RoundedCornerShape(12.dp)).padding(10.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.PlayCircle,null,tint=Cyan);Spacer(Modifier.width(8.dp));Text("DEMO SCENARIO ACTIVE · G-10",color=Cyan,fontSize=11.sp,fontWeight=FontWeight.Bold)}}
fun severityColor(v:Int)=when(v){in 0..29->Emerald;in 30..49->Amber;in 50..69->Color(0xFFFF8A4C);else->Red}
